void jit_compile_bpf_program(struct bpf_prog *prog) {
    if (!jit_enabled || !prog) {
        return;
    }

    size_t *addr_estimates = malloc(prog->len * sizeof(size_t));
    if (!addr_estimates) {
        return;
    }

    JitContext *ctx = jit_context_init();
    if (!ctx) {
        free(addr_estimates);
        return;
    }

    size_t prev_size = 0;
    size_t current_size = estimate_jit_image_size(prog, addr_estimates);

    while (current_size != prev_size) {
        prev_size = current_size;
        current_size = estimate_jit_image_size(prog, addr_estimates);
    }

    uint8_t *jit_code = malloc(current_size);
    if (!jit_code) {
        jit_context_cleanup(ctx);
        free(addr_estimates);
        return;
    }

    if (!generate_jit_code(prog, ctx, jit_code, current_size, addr_estimates)) {
        free(jit_code);
        jit_context_cleanup(ctx);
        free(addr_estimates);
        return;
    }

    prog->bpf_func = (void *)jit_code;
    prog->jited = 1;

    free(jit_code);
    jit_context_cleanup(ctx);
    free(addr_estimates);
}

void bpf_jit_compile(struct bpf_prog *prog) {
    if (!prog || !jit_enabled)
        return;

    size_t *addr_estimate = malloc(prog->len * sizeof(size_t));
    if (!addr_estimate)
        return;

    struct jit_context ctx = { .prog = prog, .addr_estimate = addr_estimate };
    size_t size_estimate = estimate_jit_image_size(prog->len);

    size_t prev_size = 0;
    do {
        prev_size = size_estimate;
        size_estimate = generate_jit_code(&ctx);
    } while (size_estimate != prev_size);

    void *jit_image = malloc(size_estimate);
    if (!jit_image) {
        free(addr_estimate);
        return;
    }

    generate_jit_code(&ctx);

    prog->bpf_func = jit_image;
    prog->jited = 1;

    free(addr_estimate);
    free(jit_image);
}

void bpf_jit_compile(struct bpf_prog *prog) {
    if (!prog || !jit_enabled())
        return;

    size_t pass_count = 0;
    size_t prev_size = 0;
    size_t estimated_size = estimate_jit_image_size(prog->len);

    void *jit_context = create_jit_context();
    void *jit_image = NULL;

    while (1) {
        void *pass_image = generate_jit_code(jit_context, prog, pass_count, &estimated_size);

        if (!pass_image) {
            destroy_jit_context(jit_context);
            return;
        }

        if (pass_count > 0 && estimated_size == prev_size)
            break;

        prev_size = estimated_size;
        pass_count++;
        free(jit_image);
        jit_image = pass_image;
    }

    prog->bpf_func = jit_image;
    prog->jited = 1;

    destroy_jit_context(jit_context);
}

void bpf_jit_compile(struct bpf_prog *prog) {
    if (!prog || !jit_enabled)
        return;

    size_t num_insns = prog->len;
    size_t estimated_size = estimate_jit_image_size(num_insns);
    void *jit_context = create_jit_context();

    if (!jit_context)
        return;

    size_t prev_size = 0;
    void *jit_image = NULL;

    while (true) {
        if (estimated_size != prev_size) {
            if (jit_image)
                free(jit_image);
            jit_image = allocate_jit_image(estimated_size);
            if (!jit_image)
                break;
            prev_size = estimated_size;
        }

        bool size_changed = generate_jit_code(jit_context, prog, jit_image, estimated_size);

        if (!size_changed)
            break;
    }

    if (jit_image) {
        prog->bpf_func = jit_image;
        prog->jited = 1;
    }

    cleanup_jit_context(jit_context);
}

void jit_compile_bpf_prog(struct bpf_prog *prog) {
    if (!jit_enabled || !prog)
        return;

    size_t estimated_size = estimate_jit_image_size(prog->len);
    void *ctx = init_jit_context();

    size_t prev_size = 0;
    size_t current_size = estimated_size;

    while (current_size != prev_size) {
        prev_size = current_size;
        current_size = generate_jit_code(ctx, prog);
        if (current_size > estimated_size) {
            estimated_size = current_size;
        }
    }

    void *jit_binary = allocate_jit_binary(estimated_size);
    if (!jit_binary)
        return;

    finalize_jit_code(ctx, jit_binary, estimated_size);
    prog->jit_func = jit_binary;
    prog->jited = 1;

    cleanup_jit_context(ctx);
}
